        qupvt.calc_noise(
          cod_info,
          l3_xmin,
          distort,
          best_noise_info,
          prev_noise
        );
        best_noise_info.bits = cod_info.part2_3_length;
        cod_info_w.assign(cod_info);
        var age = 0;
